options.helpers:
const getNumber = value => {
  const parsed = parseFloat(String(value).replace(/[^0-9.-]/g, ""));
  return isNaN(parsed) ? 0 : parsed;
};

const formatCurrency = value => {
  const number = getNumber(value);
  if (number >= 1000000000) {
    return "$" + (number / 1000000000).toFixed(1).replace(/\.0$/, "") + "B";
  }
  if (number >= 1000000) {
    return "$" + (number / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  }
  if (number >= 1000) {
    return "$" + (number / 1000).toFixed(1).replace(/\.0$/, "") + "K";
  }
  return "$" + number.toLocaleString("en-AU", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  });
};

const assetValueHeader = document.getElementById("assetValueHeader");
if (assetValueHeader) {
  assetValueHeader.innerText = formatCurrency(assetValueHeader.getAttribute("data-value"));
}

const unsupportedAssetValue = document.getElementById("unsupportedAssetValue");
if (unsupportedAssetValue) {
  unsupportedAssetValue.innerText = formatCurrency(unsupportedAssetValue.getAttribute("data-value"));
}

const riskValueElement = document.getElementById("overallRiskValue");
const riskBadge = document.getElementById("riskBadge");
const riskBar = document.getElementById("riskBar");
const riskCard = document.getElementById("overallRiskCard");
const riskDescription = document.getElementById("riskDescription");

if (riskValueElement) {
  const score = getNumber(riskValueElement.innerText);
  const boundedScore = Math.max(0, Math.min(score, 100));
  let badge = "Healthy";
  let description = "Low lifecycle support exposure";
  let color = "#22c55e";

  if (score >= 80) {
    badge = "Critical";
    description = "Critical lifecycle support exposure";
    color = "#b91c1c";
  } else if (score >= 60) {
    badge = "High";
    description = "High lifecycle support exposure";
    color = "#ef4444";
  } else if (score >= 40) {
    badge = "Elevated";
    description = "Elevated lifecycle support exposure";
    color = "#f97316";
  } else if (score >= 20) {
    badge = "Watch";
    description = "Moderate lifecycle support exposure";
    color = "#eab308";
  }

  if (riskBadge) {
    riskBadge.innerText = badge;
    riskBadge.style.backgroundColor = color;
    riskBadge.style.color = "#ffffff";
  }

  if (riskBar) {
    riskBar.style.width = boundedScore + "%";
    riskBar.style.backgroundColor = color;
  }

  if (riskCard) {
    riskCard.style.borderTopColor = color;
  }

  if (riskDescription) {
    riskDescription.innerText = description;
  }
}

options.styles:
.asset-risk-dashboard {
  width: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #eef3f8;
  color: #102a43;
  font-family: "Segoe UI", Arial, sans-serif;
}

.asset-risk-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.asset-risk-title {
  color: #102a43;
  font-size: 23px;
  font-weight: 600;
}

.asset-risk-subtitle {
  margin-top: 4px;
  color: #627d98;
  font-size: 13px;
}

.risk-summary {
  padding: 10px 14px;
  border: 1px solid #d4deea;
  border-radius: 7px;
  background: #ffffff;
  text-align: right;
}

.risk-summary-label {
  display: block;
  color: #627d98;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.risk-summary-value {
  display: block;
  margin-top: 3px;
  color: #102a43;
  font-size: 20px;
  font-weight: 700;
}

.asset-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(180px, 1fr));
  gap: 14px;
}

.asset-kpi-card {
  position: relative;
  min-height: 128px;
  box-sizing: border-box;
  overflow: hidden;
  padding: 20px 17px 15px;
  border: 1px solid #d4deea;
  border-radius: 7px;
  background: #ffffff;
  box-shadow: 0 2px 5px rgba(16, 42, 67, 0.09);
}

.asset-kpi-card::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 4px;
  content: "";
  background: #4c9aff;
}

.asset-kpi-label {
  min-height: 28px;
  color: #486581;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  line-height: 1.3;
  text-transform: uppercase;
}

.asset-kpi-value {
  margin-top: 6px;
  color: #102a43;
  font-size: 35px;
  font-weight: 700;
  line-height: 1;
}

.asset-kpi-description {
  margin-top: 9px;
  color: #829ab1;
  font-size: 11px;
  line-height: 1.35;
}

.risk-score-suffix {
  margin-left: 3px;
  color: #829ab1;
  font-size: 15px;
  font-weight: 600;
}

.risk-badge {
  display: inline-block;
  margin-top: 9px;
  padding: 4px 9px;
  border-radius: 12px;
  background: #dcfce7;
  color: #166534;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.card-blue::before {
  background: #4c9aff;
}

.card-red::before {
  background: #e5484d;
}

.card-dark-red::before {
  background: #b42318;
}

.card-orange::before {
  background: #f47b20;
}

.card-amber::before {
  background: #f59e0b;
}

.card-yellow::before {
  background: #eab308;
}

.card-teal::before {
  background: #14b8a6;
}

.card-green::before {
  background: #22a06b;
}

@media screen and (max-width: 1100px) {
  .asset-kpi-grid {
    grid-template-columns: repeat(2, minmax(180px, 1fr));
  }
}

@media screen and (max-width: 600px) {
  .asset-risk-header {
    display: block;
  }

  .risk-summary {
    margin-top: 12px;
    text-align: left;
  }

  .asset-kpi-grid {
    grid-template-columns: 1fr;
  }
}

.remediation-panel {
  height: 100%;
  box-sizing: border-box;
  padding: 18px;
  border-radius: 8px;
  background: #ffffff;
  border: 1px solid #cbd5e1;
  box-shadow: 0 3px 8px rgba(15, 23, 42, 0.08);
}

.remediation-title {
  color: #0f172a;
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 8px;
}

.remediation-subtitle {
  color: #52606d;
  font-size: 13px;
  line-height: 1.4;
  margin-bottom: 18px;
}

.remediation-actions {
  margin-top: auto;
}

.crq-button {
  display: block;
  width: 100%;
  box-sizing: border-box;
  padding: 14px;
  border-radius: 8px;
  background: #f47b20;
  color: #ffffff !important;
  text-decoration: none !important;
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  border: 0;
  cursor: pointer;
  transition: all 0.2s ease;
}

.crq-button:hover {
  background: #ea580c;
  box-shadow: 0 4px 10px rgba(244, 123, 32, 0.35);
}

.crq-button:active {
  transform: translateY(1px);
}
